ok(el('alertBox').innerHTML.indexOf('缺 ocfd2y') < 0, 'bug2 ocfd2y=number 时预警也不报缺 ocfd2y（两处口径一致）');

// bug(本轮): number 形式且越线时，持仓表徽章也必须出现（与红条对齐），不能只红条不徽章
P.applyConfig({
  targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, governance: 'state', ocfd2y: 0.8, payout2y: 85, vol: 10 }],
  rules: sandbox.PANEL_CONFIG.rules, margin: sandbox.PANEL_CONFIG.margin
});
P.render();
const _holdHtml = el('holdBody').innerHTML;
ok(_holdHtml.indexOf('连续两年分红无现金支撑') >= 0, 'hold徽章: ocfd2y=0.8(number) 越线 → 持仓表标红');
ok(_holdHtml.indexOf('连续两年支付率') >= 0, 'hold徽章: payout2y=85(number) 越线 → 持仓表标红');
ok(el('alertBox').innerHTML.indexOf('OCF/分红连续两年') >= 0, 'alerts红条: 同一数据也出红条（两处一致）');

// 自定义阈值生效：payoutMax=95 时 85 不再越线（徽章与红条同步消失）
P.applyConfig({
  targets: [{ code: '601000', name: '唐山港', ind: '交运', mkt: '沪', w: 60, governance: 'state', ocfd2y: 0.8, payout2y: 85, vol: 10 }],
  rules: sandbox.PANEL_CONFIG.rules,
  margin: Object.assign({}, sandbox.PANEL_CONFIG.margin, { payoutMax: 95 })
});
P.render();
ok(el('holdBody').innerHTML.indexOf('连续两年支付率') < 0, '阈值生效: payoutMax=95 时 85 不触发徽章');
ok(el('alertBox').innerHTML.indexOf('支付率连续两年') < 0, '阈值生效: payoutMax=95 时 85 不出红条');
